// Get document template
async getDocumentTemplate (selectedValue) {
    const selectedType = selectedValue;        
    const typeData = this.modelItem.builder.documentGroups.find(document => document.id === selectedType);


    this.isDocumentReady = true;

    const response =  await this.$axios({
        buildURL: {
            key: "admin.signatureRequest.downloadTemplate",
            params: {
                documentHeaderId: typeData.id,
                countryId: this.modelItem.editing.data.selectedCountry || 1,
            },    
        },
        responseType: 'blob',
    });

    if (!response) return;

    const blobUrl = window.URL.createObjectURL(response);

    const a = document.createElement('a');
    a.href = blobUrl;
    a.download = `Plantilla del grupo ${typeData.name}_${moment().format('DD-MM-YYYY h-m-s')}`;
    a.style.display = 'none';

    document.body.appendChild(a);
    a.click();

    window.URL.revokeObjectURL(blobUrl);
    document.body.removeChild(a);    

},

//Import template file
async importTemplateFile () {

    const file = this.modelItem.editing.data.file;
    const selectedValue = this.modelItem.editing.data.documentGroup;
    const typeData = this.modelItem.builder.documentGroups.find(document => document.id === selectedValue);

    const formData = new FormData();
    formData.append('file', file); 
    formData.append('documentHeaderId', typeData.id); 
    formData.append('countryId', this.modelItem.editing.data.selectedCountry || 1); 

    try {
        const response = await this.$axios({
            method: 'POST',
            buildURL: {
                key: 'admin.signatureRequest.importTemplate',
            },
            data: formData,             
            alert: true,
            headers: { 'Content-Type': 'multipart/form-data' }
        });

        if (response.status == true && response.data && response.data.errors.length == 0) {
            this.data = response.data.data;

            this.fillTable(response.data.data, response.data.documentHeaderId);
            this.errors = [];

        } else {

            this.errors = response.data.errors;

        }

    } catch (error) {
        console.log(error);

    } 
},

transformResponse(originalResponses) {
    return originalResponses.map((originalResponse, index) => {
        const { signerFields, contractNumber, expiresInDays } = originalResponse;

        const signers = [];
        const signerKeys = Object.keys(signerFields).filter(key =>
            key.match(/Firmante\d+_Nombre/)
        );

        signerKeys.forEach(key => {
            const signerIndex = key.match(/Firmante(\d+)_Nombre/)[1];

            const signer = {
                nombres: signerFields[`Firmante${signerIndex}_Nombre`] || "",
                apellidos: signerFields[`Firmante${signerIndex}_Apellido`] || "",
