duplicateEmail(index) {
    return (v) => {
        const email = v.trim();

        if (!email) {
            return 'Este campo es obligatorio';
        }

        const duplicate = this.recipients.some((recipient, idx) => {
            return recipient.email.trim().toLowerCase() === email.toLowerCase() && idx !== index;
        });

        if (duplicate) {
            return 'Este correo ya ha sido añadido';
        }

        return true; 
    };
