transformResponse(originalResponses) {
    return originalResponses.map((originalResponse, index) => {
        const { signerFields, contractNumber, expiresInDays } = originalResponse;

        const signers = [];
        const signerKeys = Object.keys(signerFields).filter(key =>
            key.match(/Firmante\d+_Nombre/)
        );

        signerKeys.forEach(key => {
            const signerIndex = key.match(/Firmante(\d+)_Nombre/)[1];

            const signer = {
                nombres: signerFields[`Firmante${signerIndex}_Nombre`] || "",
                apellidos: signerFields[`Firmante${signerIndex}_Apellido`] || "",
                correo: signerFields[`Firmante${signerIndex}_Correo`] || "",
                tipo_documento: signerFields[`Firmante${signerIndex}_Tipo_documento`] || "",
                tipo_documento_map:
                this.idTypeMapping[signerFields[`Firmante${signerIndex}_Tipo_documento`]] || "",
                documento: signerFields[`Firmante${signerIndex}_Documento`] || "",
                signer_order: parseInt(signerIndex),
            };

            signers.push(signer);
        });

        if (signers.length === 0 && this.modelItem.default_signers) {
            this.modelItem.default_signers.forEach((defaultSigner, idx) => {
                signers.push({
                    nombres: defaultSigner.firstname || "",
                    apellidos: defaultSigner.lastname || "",
                    correo: defaultSigner.email || "",
                    tipo_documento: defaultSigner.document_type || "",
                    tipo_documento_map: this.idTypeMapping[defaultSigner.document_type] || "",
                    documento: defaultSigner.id_number || "",
                    signer_order: idx + 1,
                });
            });
        }

        const signerOrder2 =
            signers.find((s) => s.signer_order === 2) ||
            signers.find((s) => s.signer_order === 1) ||
            signers[0] || {};

        return {
            contract_number: contractNumber,
            expires_in_days: expiresInDays,
            signers: signers,
            signerOrder2: signerOrder2,
            selectable: true,
            uid: `${contractNumber}-${index}`,
        };
    });
},

