435→function adjustSignatureFields(fields) { 
436→    let parsedFields;
437→    try {
438→        parsedFields = typeof fields === "string" ? JSON.parse(fields) : fields;
439→    } catch (error) {
440→        console.error("Error parsing fields JSON:", error);
441→        return fields; 
442→    }
443→    
444→    return parsedFields.map(field => {
445→        if (field.type === 'signature') {
446→            field.left = field.left - 2;      
447→            field.width = field.width - 2;    
448→            field.height = field.height; 
449→            field.top = field.top - 2;   
450→        }
451→        return field;
452→    });
453→}
