649→                   let rawValue = cell ? cell.value : null;
650→                    let value = cleanCellValue(rawValue);
651→
652→                    if (typeof value === 'object' && value && value.text) {
653→                        value = value.text;
654→                    }
655→
656→                    if (header.startsWith('VAR_')) {
657→                        const varName = header.replace('VAR_', '');
658→                        
659→                        if (value === null || value === undefined || String(value).trim() === '') {
