665→                        return; 
666→                    }
667→
668→                    if (value === null || value === '') {
669→                        errorsRow.push(`La celda "${header}" en la fila ${rowNumber} no tiene valor.`);
670→                    }
671→
672→                    if (header.includes('Correo')) {
673→                        if (!isValidEmail(value)) {
674→                            errorsRow.push(`El valor en la celda "${header}" en la fila ${rowNumber} no es un correo válido.`);
675→                        } else {
676→                            signerFields[header] = value;
677→                        }
678→                    } else if (header.includes('Celular')) {
679→                        if (!isValidPhoneNumber(value)) {
680→                            errorsRow.push(`El valor en la celda "${header}" en la fila ${rowNumber} no es válido. Debe ser numérico y tener entre 10 y 14 dígitos.`);
681→                        } else {
682→                            signerFields[header] = value;
683→                        }
684→                    } else if (header.includes('Tipo_documento')) {
685→                        const documentTypeName = value;
686→                        const documentTypeId = documentTypeIdMap[documentTypeName];
687→                        if (!documentTypeId) {
688→                            errorsRow.push(`El Tipo_documento "${documentTypeName}" en la fila ${rowNumber} no es válido.`);
689→                        } else {
690→                            signerFields[header] = documentTypeId;
691→                            const signerKey = header.split('_')[0];
692→                            tipoDocumentoPerSigner[signerKey] = documentTypeId;
693→                        }
694→                    } else if (header.includes('Documento')) {
695→                        signerFields[header] = value;
696→
697→                    } else if (signers.includes(header)) {
698→                        if (value === null || value === '') {
699→                            errorsRow.push(`El campo "${header}" en la fila ${rowNumber} no tiene valor.`);
700→                        } else {
701→                            signerFields[header] = value;
702→                        }
703→                    } else {
704→                        dynamicFields[header] = value;
705→                    }
706→                });
707→
708→                console.log(errorsRow);
709→                if (errorsRow.length === 0) {
710→
711→
712→                    dataArr.push({ expiresInDays: expiresDate, contractNumber, dynamicFields, signerFields, variableValues });
713→                } else {
714→                    errors = errors.concat(errorsRow);
715→                }
716→            }
717→        });
718→
719→        fs.unlink(file.path, (err) => {
720→            if (err) throw err;
721→            console.log(`Archivo eliminado: ${file.path}`);
722→        });
723→
724→        res.status(200).send({
725→            status: true,
726→            data: {
