 482→async function importDocumentsPackagesFields(req, res) {
 483→
 484→    if (!req.file) {
 485→        return res.status(400).send({
 486→          status: false,
 487→          message: "No se ha subido ningún archivo",
 488→          errors: [
 489→            {
 490→              field_name: "file",
 491→            },
 492→          ],
 493→        });
 494→    }
 495→
 496→    const countryId = req.body.countryId;
 497→
 498→    const file = req.file;
 499→    const workbook = new ExcelJS.Workbook();
 500→
 501→    await workbook.xlsx.readFile(file.path);
 502→
 503→    const worksheet = workbook.getWorksheet(1);
 504→    if (!worksheet) {
 505→        return res.status(400).send({
 506→            status: false,
 507→            message: "El archivo no contiene hojas válidas.",
 508→            errors: [{ field_name: "file" }],
 509→        });
 510→    }
 511→        
 512→    let hasData = false;
 513→    worksheet.eachRow((row, rowNumber) => {
 514→        if (rowNumber > 1) {
 515→            let rowHasRealData = false;
 516→    
 517→            row.eachCell({ includeEmpty: true }, (cell, colNumber) => {
 518→                if (cell.value !== null && cell.value !== '' && typeof cell.value !== 'object') {
 519→                    rowHasRealData = true;
 520→                }
 521→            });
 522→    
 523→            if (rowHasRealData) {
 524→                hasData = true;
 525→            } else {
 526→                console.log(`Fila ${rowNumber} solo contiene validaciones o está vacía.`);
 527→            }
 528→        }
 529→    });
 530→    
 531→    if (!hasData) {
 532→        return res.status(400).send({
 533→            status: false,
 534→            message: "El archivo está vacío o solo contiene validaciones de datos sin valores.",
 535→            errors: [{ field_name: "file" }],
 536→        });
 537→    }
 538→
 539→    try {
 540→        const documentTypes = await db.identification_types.findMany({
 541→            where: {
 542→                country_id: parseInt(countryId),
 543→            },
 544→            select: {
 545→                id: true,
 546→                name: true,
 547→                field_type: true,
 548→            }
 549→        });
 550→
 551→        const documentTypeMap = {};
 552→        const documentTypeIdMap = {};
 553→
 554→        documentTypes.forEach(type => {
 555→            documentTypeMap[type.name] = type.field_type;
 556→            documentTypeIdMap[type.name] = type.id;
 557→        });
 558→
 559→       
 560→        let headers = {};
 561→        let fields = [];
 562→        let signers = [];
 563→        let variableHeaders = [];
 564→
 565→        worksheet.getRow(1).eachCell((cell, colNumber) => {
 566→            headers[cell.text] = colNumber;
 567→            if (cell.text.startsWith('Firmante')) {
 568→                signers.push(cell.text);
 569→            } else if (cell.text.startsWith('VAR_')) {
 570→                variableHeaders.push(cell.text);
 571→            } else if (!['Fecha y hora límite para realizar la firma', 'Número de contrato'].includes(cell.text)) {
 572→                fields.push(cell.text);
 573→            }
 574→        });
 575→
 576→        let dataArr = [];
 577→        let errors = []; 
 578→
 579→        const isValidEmail = (email) => {
 580→            return /\S+@\S+\.\S+/.test(email);
 581→        };
 582→
 583→        const isValidPhoneNumber = (phone) => {
 584→            return /^\d{10,14}$/.test(phone);
 585→        };
 586→
 587→
 588→        worksheet.eachRow({ includeEmpty: true }, function(row, rowNumber) {
 589→            if (rowNumber !== 1) { 
 590→
 591→                let isRowEmpty = true;
 592→                row.eachCell({ includeEmpty: true }, function(cell, colNumber) {
 593→                    if (cell.value !== null && cell.value !== '') {
 594→                        isRowEmpty = false;
 595→                    }
 596→                });
 597→
 598→                if (row.actualCellCount === 0 || row.values.every(cell => cell === null || cell === '')) {
 599→                    return;
 600→                }
 601→                
 602→                let errorsRow = [];
 603→
 604→                const expiresInDaysCell = row.getCell(headers['Fecha límite para realizar la firma']);
 605→                const expiresInDays = expiresInDaysCell ? expiresInDaysCell.value : null;
 606→
 607→                let expiresDate;
 608→                if (!expiresInDays) {
 609→                    errorsRow.push(`La fecha en la fila ${rowNumber} no tiene valor.`);
 610→                } else {
 611→                    if (expiresInDays instanceof Date) {
 612→                        expiresDate = expiresInDays;
 613→                    } else if (typeof expiresInDays === 'string' || typeof expiresInDays === 'number') {
 614→                        expiresDate = new Date(expiresInDays);
 615→                        if (isNaN(expiresDate)) {
 616→                            errorsRow.push(`La fecha en la fila ${rowNumber} no es válida.`);
 617→                        }
 618→                    } else {
 619→                        errorsRow.push(`La fecha en la fila ${rowNumber} no es válida.`);
 620→                    }
 621→
 622→                    if (expiresDate) {
 623→                        const today = new Date();
 624→                        today.setHours(0, 0, 0, 0);
 625→                
 626→                        expiresDate.setHours(0, 0, 0, 0);
 627→                
 628→                        if (expiresDate < today) {
 629→                            errorsRow.push(`La fecha en la fila ${rowNumber} debe ser igual o mayor a la fecha actual.`);
 630→                        }
 631→                    }
 632→                }
 633→
 634→                const contractNumberCell = row.getCell(headers['Número de contrato']);
 635→                const contractNumber = contractNumberCell ? contractNumberCell.value : null;
 636→
 637→                if (contractNumber == null || contractNumber === '') {
 638→                    errorsRow.push(`El campo "Número de contrato" en la fila ${rowNumber} no tiene valor.`);
 639→                }
 640→
 641→                let dynamicFields = {};
 642→                let signerFields = {};
 643→                let variableValues = {};
 644→                let tipoDocumentoPerSigner = {};
 645→
 646→                Object.keys(headers).forEach((header) => {
 647→                    const colIndex = headers[header];
 648→                    let cell = row.getCell(colIndex);
 649→                   let rawValue = cell ? cell.value : null;
 650→                    let value = cleanCellValue(rawValue);
 651→
 652→                    if (typeof value === 'object' && value && value.text) {
 653→                        value = value.text;
 654→                    }
 655→
 656→                    if (header.startsWith('VAR_')) {
 657→                        const varName = header.replace('VAR_', '');
 658→                        
 659→                        if (value === null || value === undefined || String(value).trim() === '') {
 660→                            errorsRow.push(`La variable "${header}" en la fila ${rowNumber} está vacía.`);
 661→                            variableValues[varName] = '';
 662→                        } else {
 663→                            variableValues[varName] = String(value);
 664→                        }
 665→                        return; 
 666→                    }
 667→
 668→                    if (value === null || value === '') {
 669→                        errorsRow.push(`La celda "${header}" en la fila ${rowNumber} no tiene valor.`);
 670→                    }
 671→
 672→                    if (header.includes('Correo')) {
 673→                        if (!isValidEmail(value)) {
 674→                            errorsRow.push(`El valor en la celda "${header}" en la fila ${rowNumber} no es un correo válido.`);
 675→                        } else {
 676→                            signerFields[header] = value;
 677→                        }
 678→                    } else if (header.includes('Celular')) {
 679→                        if (!isValidPhoneNumber(value)) {
 680→                            errorsRow.push(`El valor en la celda "${header}" en la fila ${rowNumber} no es válido. Debe ser numérico y tener entre 10 y 14 dígitos.`);
 681→                        } else {
 682→                            signerFields[header] = value;
 683→                        }
 684→                    } else if (header.includes('Tipo_documento')) {
 685→                        const documentTypeName = value;
 686→                        const documentTypeId = documentTypeIdMap[documentTypeName];
 687→                        if (!documentTypeId) {
 688→                            errorsRow.push(`El Tipo_documento "${documentTypeName}" en la fila ${rowNumber} no es válido.`);
 689→                        } else {
 690→                            signerFields[header] = documentTypeId;
 691→                            const signerKey = header.split('_')[0];
 692→                            tipoDocumentoPerSigner[signerKey] = documentTypeId;
 693→                        }
 694→                    } else if (header.includes('Documento')) {
 695→                        signerFields[header] = value;
 696→
 697→                    } else if (signers.includes(header)) {
 698→                        if (value === null || value === '') {
 699→                            errorsRow.push(`El campo "${header}" en la fila ${rowNumber} no tiene valor.`);
 700→                        } else {
 701→                            signerFields[header] = value;
 702→                        }
 703→                    } else {
 704→                        dynamicFields[header] = value;
 705→                    }
 706→                });
 707→
 708→                console.log(errorsRow);
 709→                if (errorsRow.length === 0) {
 710→
 711→
 712→                    dataArr.push({ expiresInDays: expiresDate, contractNumber, dynamicFields, signerFields, variableValues });
 713→                } else {
 714→                    errors = errors.concat(errorsRow);
 715→                }
 716→            }
 717→        });
 718→
 719→        fs.unlink(file.path, (err) => {
 720→            if (err) throw err;
 721→            console.log(`Archivo eliminado: ${file.path}`);
 722→        });
 723→
 724→        res.status(200).send({
 725→            status: true,
 726→            data: {
 727→                data: dataArr,
 728→                documentHeaderId: req.body.documentHeaderId,
 729→                errors: errors,
 730→            },
 731→            message: "Datos recibidos correctamente",
 732→        });
 733→
 734→    } catch (err) {
 735→        console.log(err);
 736→        res.status(404).send({
 737→            status: false,
 738→            message: err,
 739→        });
 740→    }
 741→}
